def min_absolute_difference():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    W = list(map(int, data[1:]))

    total_sum = sum(W)
    half_sum = total_sum // 2

    dp = [False] * (half_sum + 1)
    dp[0] = True

    for weight in W:
        for j in range(half_sum, weight - 1, -1):
            if dp[j - weight]:
                dp[j] = True

    for j in range(half_sum, -1, -1):
        if dp[j]:
            S1 = j
            break

    S2 = total_sum - S1
    print(abs(S2 - S1))
